      seed: other.seed ?? seed,
      seedVariant: other.seed != null ? other.seedVariant : seedVariant,
      neutral: other.neutral ?? neutral,
      primary: other.primary ?? primary,
      onPrimary: other.onPrimary ?? onPrimary,
      primaryContainer: other.primaryContainer ?? primaryContainer,
      onPrimaryContainer: other.onPrimaryContainer ?? onPrimaryContainer,
      secondary: other.secondary ?? secondary,
      onSecondary: other.onSecondary ?? onSecondary,
      secondaryContainer: other.secondaryContainer ?? secondaryContainer,
      onSecondaryContainer: other.onSecondaryContainer ?? onSecondaryContainer,
      tertiary: other.tertiary ?? tertiary,
      onTertiary: other.onTertiary ?? onTertiary,
      tertiaryContainer: other.tertiaryContainer ?? tertiaryContainer,
      onTertiaryContainer: other.onTertiaryContainer ?? onTertiaryContainer,
      background: other.background ?? background,
      surface: other.surface ?? surface,
      surfaceElevated: other.surfaceElevated ?? surfaceElevated,
      fill: other.fill ?? fill,
      inverseSurface: other.inverseSurface ?? inverseSurface,
      onInverseSurface: other.onInverseSurface ?? onInverseSurface,
      text: other.text ?? text,
      textSecondary: other.textSecondary ?? textSecondary,
      textTertiary: other.textTertiary ?? textTertiary,
      textDisabled: other.textDisabled ?? textDisabled,
      link: other.link ?? link,
      border: other.border ?? border,
      divider: other.divider ?? divider,
      focus: other.focus ?? focus,
      error: other.error ?? error,
      onError: other.onError ?? onError,
      errorContainer: other.errorContainer ?? errorContainer,
      onErrorContainer: other.onErrorContainer ?? onErrorContainer,
      success: other.success ?? success,
      onSuccess: other.onSuccess ?? onSuccess,
      successContainer: other.successContainer ?? successContainer,
      onSuccessContainer: other.onSuccessContainer ?? onSuccessContainer,
      warning: other.warning ?? warning,
      onWarning: other.onWarning ?? onWarning,
