      onWarningContainer: other.onWarningContainer ?? onWarningContainer,
      info: other.info ?? info,
      onInfo: other.onInfo ?? onInfo,
      infoContainer: other.infoContainer ?? infoContainer,
      onInfoContainer: other.onInfoContainer ?? onInfoContainer,
